// Check if character is unreserved
function isUnreserved(code) {
  return (
    (code >= 0x41 && code <= 0x5a) || // A-Z
    (code >= 0x61 && code <= 0x7a) || // a-z
    (code >= 0x30 && code <= 0x39) || // 0-9
    code === 0x2d || // -
    code === 0x2e || // .
    code === 0x5f || // _
    code === 0x7e // ~
  )
}

// Normalize percent-encodings in a component
// Returns the normalized string or null if invalid
function normalizePercentEncodings(component, componentName, lineNum) {
  let result = ''
  for (let i = 0; i < component.length; i++) {
    if (component[i] === '%') {
      if (i + 2 >= component.length) {
        process.stderr.write(`error: line ${lineNum}: the ${componentName} has a truncated percent-encoding\n`)
        process.exit(2)
      }
      const hex = component.substring(i + 1, i + 3)
      // Check if valid hex
      if (!/^[0-9a-fA-F]{2}$/.test(hex)) {
