// Normalize a URI
function normalizeURI(uri, lineNum) {
  // Lowercase scheme
  if (uri.scheme !== null) {
    uri.scheme = uri.scheme.toLowerCase()
  }

  // Normalize percent-encodings (in order: userinfo, host, path, query, fragment)
  if (uri.authority !== null) {
    // Parse authority into userinfo, host, port
    let userinfo = null
    let host = null
    let port = null

    // Find the last @ to split userinfo from host:port
    let lastAtIdx = uri.authority.lastIndexOf('@')
    let hostport
    if (lastAtIdx !== -1) {
      userinfo = uri.authority.substring(0, lastAtIdx)
      hostport = uri.authority.substring(lastAtIdx + 1)
    } else {
      hostport = uri.authority
    }

    // Normalize userinfo
    if (userinfo !== null) {
      userinfo = normalizePercentEncodings(userinfo, 'userinfo', lineNum)
    }

    // Find the host and port
    // Port is everything after the first : that follows the last ]
    let lastBracketIdx = hostport.lastIndexOf(']')
    let colonIdx = -1
    if (lastBracketIdx !== -1) {
      colonIdx = hostport.indexOf(':', lastBracketIdx)
    } else {
      colonIdx = hostport.indexOf(':')
    }

    if (colonIdx !== -1) {
      host = hostport.substring(0, colonIdx)
      port = hostport.substring(colonIdx + 1)
    } else {
      host = hostport
    }

    // Normalize host percent-encodings
    host = normalizePercentEncodings(host, 'host', lineNum)

    // Lowercase host
    host = host.toLowerCase()

    // Check for default port and drop if needed
    if (port !== null && port !== '') {
      const defaultPorts = {
        'http': '80',
        'ws': '80',
        'https': '443',
        'wss': '443',
        'ftp': '21'
      }
      const scheme = uri.scheme || ''
      if (defaultPorts[scheme] && port === defaultPorts[scheme]) {
        port = null
      }
