  uri.path = normalizePercentEncodings(uri.path, 'path', lineNum)

  // Normalize percent-encodings in query
  if (uri.query !== null) {
    uri.query = normalizePercentEncodings(uri.query, 'query', lineNum)
  }

  // Normalize percent-encodings in fragment
  if (uri.fragment !== null) {
    uri.fragment = normalizePercentEncodings(uri.fragment, 'fragment', lineNum)
  }

  // Remove dot segments from path
  uri.path = removeDotSegments(uri.path)

  // Add / to path when authority is present and path is empty
  if (uri.authority !== null && uri.path === '') {
    uri.path = '/'
  }

  return uri
