// Remove dot segments from path according to RFC 3986 section 5.2.4
function removeDotSegments(path) {
  const inputBuffer = path
  const outputBuffer = []

  let i = 0
  while (i < inputBuffer.length) {
    // A: If the input buffer begins with a prefix of "../" or "./"
    if (inputBuffer.substring(i, i + 3) === '../') {
      i += 3
    } else if (inputBuffer.substring(i, i + 2) === './') {
      i += 2
    }
    // B: If the input buffer begins with a prefix of "/./" or "/."
    else if (inputBuffer.substring(i, i + 3) === '/./') {
      i += 2 // skip "/./" but keep the "/"
    } else if (inputBuffer.substring(i) === '/.') {
      i += 1 // replace "/." with "/"
    }
    // C: If the input buffer begins with a prefix of "/../" or "/.."
    else if (inputBuffer.substring(i, i + 4) === '/../') {
      i += 3 // skip "/." but keep the "/"
      if (outputBuffer.length > 0) {
        outputBuffer.pop() // remove the last segment
      }
    } else if (inputBuffer.substring(i) === '/..') {
      i += 1 // replace "/.." with "/"
      if (outputBuffer.length > 0) {
        outputBuffer.pop() // remove the last segment
      }
    }
    // D: If the input buffer consists only of "." or ".."
    else if (inputBuffer.substring(i) === '.' || inputBuffer.substring(i) === '..') {
      i = inputBuffer.length
    }
    // E: Move the first path segment to the output buffer
    else {
      // Find the next "/" or end of string
      let nextSlash = inputBuffer.indexOf('/', i + 1)
      if (nextSlash === -1) {
        nextSlash = inputBuffer.length
      }
      outputBuffer.push(inputBuffer.substring(i, nextSlash))
      i = nextSlash
    }
  }

  return outputBuffer.join('')
}

// Merge a relative path onto a base path
function mergePaths(basePath, baseAuthority, refPath) {
  if (baseAuthority !== null && basePath === '') {
    return '/' + refPath
  }
  const lastSlash = basePath.lastIndexOf('/')
  if (lastSlash !== -1) {
    return basePath.substring(0, lastSlash + 1) + refPath
  }
  return refPath
}

// Resolve a reference against a base (RFC 3986 section 5.2.2)
function resolveReference(base, reference) {
  const target = new URI(null, null, '', null, null)

  if (reference.scheme !== null) {
    // Reference has a scheme: use reference as-is with dot removal
    target.scheme = reference.scheme
    target.authority = reference.authority
    target.path = removeDotSegments(reference.path)
    target.query = reference.query
  } else {
    if (reference.authority !== null) {
      // Reference has an authority: use base scheme + reference authority/path/query
      target.authority = reference.authority
      target.path = removeDotSegments(reference.path)
      target.query = reference.query
    } else {
      if (reference.path === '') {
        // Reference has empty path: use base authority and path
        target.path = base.path
        if (reference.query !== null) {
          target.query = reference.query
        } else {
          target.query = base.query
        }
      } else {
        if (reference.path.startsWith('/')) {
          // Reference path is absolute
          target.path = removeDotSegments(reference.path)
        } else {
          // Reference path is relative: merge onto base
          target.path = mergePaths(base.path, base.authority, reference.path)
          target.path = removeDotSegments(target.path)
        }
        target.query = reference.query
      }
      target.authority = base.authority
    }
    target.scheme = base.scheme
  }

  target.fragment = reference.fragment

  return target
}

