      if (base.scheme === null) {
        process.stderr.write(`error: line ${lineNum}: the base has no scheme\n`)
        process.exit(2)
      }

      const reference = parseURI(refPart)

      const resolved = resolveReference(base, reference)
      const normalized = normalizeURI(resolved, lineNum)
      console.log(normalized.toString())
    }
  }

  process.exit(0)
}

main().catch(err => {
  process.stderr.write(`error: ${err.message}\n`)
  process.exit(2)
})
