    } else if (inputBuffer.substring(i) === '/.') {
      i += 1 // replace "/." with "/"
    }
    // C: If the input buffer begins with a prefix of "/../" or "/.."
    else if (inputBuffer.substring(i, i + 4) === '/../') {
