// Resolve a reference against a base (RFC 3986 section 5.2.2)
function resolveReference(base, reference) {
  const target = new URI(null, null, '', null, null)

  if (reference.scheme !== null) {
    // Reference has a scheme: use reference as-is with dot removal
    target.scheme = reference.scheme
    target.authority = reference.authority
    target.path = removeDotSegments(reference.path)
    target.query = reference.query
  } else {
    if (reference.authority !== null) {
      // Reference has an authority: use base scheme + reference authority/path/query
      target.authority = reference.authority
      target.path = removeDotSegments(reference.path)
      target.query = reference.query
    } else {
      if (reference.path === '') {
        // Reference has empty path: use base authority and path
        target.path = base.path
        if (reference.query !== null) {
          target.query = reference.query
        } else {
          target.query = base.query
        }
      } else {
        if (reference.path.startsWith('/')) {
          // Reference path is absolute
          target.path = removeDotSegments(reference.path)
        } else {
          // Reference path is relative: merge onto base
          target.path = mergePaths(base.path, base.authority, reference.path)
          target.path = removeDotSegments(target.path)
        }
        target.query = reference.query
      }
      target.authority = base.authority
    }
    target.scheme = base.scheme
  }

  target.fragment = reference.fragment

  return target
}

// Main program
async function main() {
  const args = process.argv.slice(2)

  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }

  const mode = args[0]

  const rl = readline.createInterface({
    input: process.stdin,
    output: null,
    terminal: false
  })

  let lineNum = 0
  for await (const line of rl) {
    lineNum++

    if (mode === 'normalize') {
      const uri = parseURI(line)
      const normalized = normalizeURI(uri, lineNum)
      console.log(normalized.toString())
    } else if (mode === 'resolve') {
      // Split on first space
      const spaceIdx = line.indexOf(' ')
      if (spaceIdx === -1) {
        process.stderr.write(`error: line ${lineNum}: expected a base and a reference\n`)
        process.exit(2)
      }

      const basePart = line.substring(0, spaceIdx)
      const refPart = line.substring(spaceIdx + 1)

      const base = parseURI(basePart)

      // Check that base has a scheme
      if (base.scheme === null) {
        process.stderr.write(`error: line ${lineNum}: the base has no scheme\n`)
        process.exit(2)
      }

      const reference = parseURI(refPart)

      const resolved = resolveReference(base, reference)
      const normalized = normalizeURI(resolved, lineNum)
      console.log(normalized.toString())
    }
  }

  process.exit(0)
