#!/usr/bin/env node
/**
 * URI normalization and resolution according to RFC 3986
 */

import readline from 'readline'

// URI component interface
class URI {
  constructor(scheme, authority, path, query, fragment) {
    this.scheme = scheme // null or string
    this.authority = authority // null or string
    this.path = path // string (possibly empty)
    this.query = query // null or string
    this.fragment = fragment // null or string
  }

  toString() {
    let result = ''
    if (this.scheme !== null) {
      result += this.scheme + ':'
    }
    if (this.authority !== null) {
      result += '//' + this.authority
    }
    result += this.path
    if (this.query !== null) {
      result += '?' + this.query
    }
    if (this.fragment !== null) {
      result += '#' + this.fragment
    }
    return result
  }
}

// Parse a URI reference according to RFC 3986 section 3
function parseURI(ref) {
  let scheme = null
  let authority = null
  let path = ''
  let query = null
  let fragment = null

  // Find the fragment (from # to end)
  let fragmentIdx = ref.indexOf('#')
  if (fragmentIdx !== -1) {
    fragment = ref.substring(fragmentIdx + 1)
    ref = ref.substring(0, fragmentIdx)
  }

  // Find the query (from ? to end)
  let queryIdx = ref.indexOf('?')
  if (queryIdx !== -1) {
    query = ref.substring(queryIdx + 1)
    ref = ref.substring(0, queryIdx)
  }

  // Find the scheme (runs to first : not preceded by /, ?, or #)
  let schemeIdx = -1
  for (let i = 0; i < ref.length; i++) {
    const char = ref[i]
    if (char === ':') {
      schemeIdx = i
      break
    }
    if (char === '/' || char === '?' || char === '#') {
      break
    }
  }

  if (schemeIdx !== -1) {
    scheme = ref.substring(0, schemeIdx)
    ref = ref.substring(schemeIdx + 1)
  }

  // Find the authority (introduced by // and running to next /, ?, or #)
  if (ref.startsWith('//')) {
    let authorityEnd = ref.length
    for (let i = 2; i < ref.length; i++) {
      if (ref[i] === '/' || ref[i] === '?' || ref[i] === '#') {
        authorityEnd = i
        break
      }
    }
    authority = ref.substring(2, authorityEnd)
    ref = ref.substring(authorityEnd)
  }

  // The rest is path
  path = ref

  return new URI(scheme, authority, path, query, fragment)
}

// Check if character is unreserved
function isUnreserved(code) {
  return (
    (code >= 0x41 && code <= 0x5a) || // A-Z
    (code >= 0x61 && code <= 0x7a) || // a-z
    (code >= 0x30 && code <= 0x39) || // 0-9
    code === 0x2d || // -
    code === 0x2e || // .
    code === 0x5f || // _
    code === 0x7e // ~
  )
}

// Normalize percent-encodings in a component
// Returns the normalized string or null if invalid
function normalizePercentEncodings(component, componentName, lineNum) {
  let result = ''
  for (let i = 0; i < component.length; i++) {
    if (component[i] === '%') {
      if (i + 2 >= component.length) {
        process.stderr.write(`error: line ${lineNum}: the ${componentName} has a truncated percent-encoding\n`)
        process.exit(2)
      }
      const hex = component.substring(i + 1, i + 3)
      // Check if valid hex
      if (!/^[0-9a-fA-F]{2}$/.test(hex)) {
        process.stderr.write(`error: line ${lineNum}: the ${componentName} has a truncated percent-encoding\n`)
        process.exit(2)
      }
      const code = parseInt(hex, 16)
      if (isUnreserved(code)) {
        result += String.fromCharCode(code)
      } else {
        result += '%' + hex.toUpperCase()
      }
      i += 2
    } else {
      result += component[i]
    }
  }
  return result
}

// Normalize a URI
function normalizeURI(uri, lineNum) {
  // Lowercase scheme
  if (uri.scheme !== null) {
    uri.scheme = uri.scheme.toLowerCase()
  }

  // Normalize percent-encodings (in order: userinfo, host, path, query, fragment)
