#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { readFileSync } from 'node:fs'

import { parseURI, formatURI } from './parse.js'
import { normalizeURI, removeDotSegments } from './normalize.js'
import { resolveReference } from './resolve.js'

class Failure extends Error {
  constructor(message) {
    super(message)
    this.name = 'Failure'
  }
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch (err) {
    if (err && (err.code === 'EAGAIN' || err.code === 'ENXIO')) return ''
    throw err
  }
}

function splitRecords(text) {
  if (text === '') return []
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }
  const mode = args[0]
  const records = splitRecords(readStdin())
  const out = []

  try {
    for (let i = 0; i < records.length; i++) {
      const record = records[i]
      const lineNum = i + 1
      if (mode === 'normalize') {
        out.push(formatURI(normalizeURI(parseURI(record), lineNum, Failure)))
      } else {
        const space = record.indexOf(' ')
        if (space === -1) {
          throw new Failure(`error: line ${lineNum}: expected a base and a reference\n`)
        }
        const base = parseURI(record.slice(0, space))
        if (base.scheme === null) {
          throw new Failure(`error: line ${lineNum}: the base has no scheme\n`)
        }
        const reference = parseURI(record.slice(space + 1))
        const target = resolveReference(base, reference, removeDotSegments)
        out.push(formatURI(normalizeURI(target, lineNum, Failure)))
      }
    }
  } catch (err) {
    if (err instanceof Failure) {
      process.stderr.write(err.message)
      process.exit(2)
    }
    throw err
  }

  if (out.length > 0) process.stdout.write(out.join('\n') + '\n')
  process.exit(0)
}

main()

